// Assembles assets/js/kancamu.js from all individual JS files.
// Run: node assets/tools/assemble-bundle.mjs
import { readFileSync, writeFileSync } from "fs";
import { join, dirname } from "path";
import { fileURLToPath } from "url";

const root = join(dirname(fileURLToPath(import.meta.url)), "../..");
const jsDir = join(root, "assets/js");

// Read each source file
const read = (name) => readFileSync(join(jsDir, name), "utf8");

// --- icons.js: strip export statements, keep everything else ---
let iconsContent = read("icons.js");
// Remove: export default icons; and export { icons };
iconsContent = iconsContent
  .replace(/^export default icons;\s*$/m, "")
  .replace(/^export \{ icons \};\s*$/m, "")
  .trimEnd();

// --- cleanup.js: strip the outer IIFE wrapper (keep the inner body) ---
// It's: (() => { ... })();
// We'll keep it as a plain block inside the module
let cleanupContent = read("cleanup.js");

// --- url.js: same IIFE pattern ---
let urlContent = read("url.js");

// --- i18n.js: replace document.currentScript.src with import.meta.url ---
let i18nContent = read("i18n.js");
i18nContent = i18nContent.replace(
  'new URL("../data/brand.js", document.currentScript.src).href',
  'new URL("../data/brand.js", import.meta.url).href'
);

// --- popup.js: replace document.currentScript.src ---
let popupContent = read("popup.js");
popupContent = popupContent.replace(
  'new URL("../data/popup.js", document.currentScript.src).href',
  'new URL("../data/popup.js", import.meta.url).href'
);

// --- autocomplete.js: no currentScript usage, keep as is ---
let autocompleteContent = read("autocomplete.js");

// --- components.js: replace currentScript + remove ICONS_MODULE import ---
let componentsContent = read("components.js");
componentsContent = componentsContent.replace(
  'new URL("../data/kit.js", document.currentScript.src).href',
  'new URL("../data/kit.js", import.meta.url).href'
);
// Remove ICONS_MODULE lines (icons is now inlined above)
componentsContent = componentsContent.replace(
  /^\s*const ICONS_MODULE = new URL\("icons\.js", document\.currentScript\.src\)\.href;\s*\n/m,
  ""
);
componentsContent = componentsContent.replace(
  /^\s*import\(ICONS_MODULE\)\.catch\(\(\) => \{\}\);\s*\n/m,
  ""
);

// --- account.js: replace document.currentScript.src (two occurrences) ---
let accountContent = read("account.js");
accountContent = accountContent.replace(
  'new URL("../../youmu/", document.currentScript.src).href',
  'new URL("../../youmu/", import.meta.url).href'
);
accountContent = accountContent.replace(
  'new URL("../data/auth.js", document.currentScript.src).href',
  'new URL("../data/auth.js", import.meta.url).href'
);

// --- settings.js: no currentScript usage ---
let settingsContent = read("settings.js");

// --- storage.js: replace document.currentScript.src ---
let storageContent = read("storage.js");
storageContent = storageContent.replace(
  'new URL("../data/brand.js", document.currentScript.src).href',
  'new URL("../data/brand.js", import.meta.url).href'
);

// --- transfer.js: no currentScript usage ---
let transferContent = read("transfer.js");

// --- Assemble the bundle ---
const bundle = `// kancamu.js — the single JS bundle for all Kancamu apps.
// This file is generated by assets/tools/assemble-bundle.mjs from individual files in assets/js/.
// theme.js is NOT included here: it must run synchronously (before paint) in every HTML page.
// Load this as: <script type="module" src="...assets/js/kancamu.js"></script>

/* ============================================================
   icons.js — SVG icons + CSS auto-inject
   ============================================================ */
${iconsContent}

/* ============================================================
   cleanup.js — delete obsolete localStorage / DB / cache keys
   ============================================================ */
${cleanupContent}

/* ============================================================
   url.js — window.urlState: query-string state for each app
   ============================================================ */
${urlContent}

/* ============================================================
   i18n.js — window.i18n: language support
   ============================================================ */
${i18nContent}

/* ============================================================
   popup.js — window.popups: dialogs, sheets, toasts
   ============================================================ */
${popupContent}

/* ============================================================
   autocomplete.js — window.autocomplete: search suggestions
   ============================================================ */
${autocompleteContent}

/* ============================================================
   components.js — window.components: shared UI helpers & kit-* tags
   ============================================================ */
${componentsContent}

/* ============================================================
   account.js — window.account: GitHub sign-in
   ============================================================ */
${accountContent}

/* ============================================================
   settings.js — window.settings: per-app settings in localStorage
   ============================================================ */
${settingsContent}

/* ============================================================
   storage.js — window.storage: GitHub repository storage
   ============================================================ */
${storageContent}

/* ============================================================
   transfer.js — window.transfer: drag-and-drop file transfer
   ============================================================ */
${transferContent}
`;

writeFileSync(join(jsDir, "kancamu.js"), bundle, "utf8");
console.log("kancamu.js written successfully.");
console.log(`Size: ${(bundle.length / 1024).toFixed(1)} KB`);
